def parse_price(s: str) -> float:
    import re
    # Remove dollar sign and split by commas and dots
    cleaned = re.sub(r'[,$]', '', s)
    # Split into whole number and decimal parts
    if '.' in cleaned:
        whole, decimal = cleaned.split('.')
    else:
        whole, decimal = cleaned, ''
    # Remove commas from whole number part
    whole = whole.replace(',', '')
    # Combine and convert to float
    return float(f'{whole}.{decimal}' if decimal else whole)

def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result = ''
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            result += s[i-1] + str(count)
            count = 1
    result += s[-1] + str(count)
    return result

